if(!exists('evaluate_decision_grid'))library(creditratingsystem)
dv_hash<-if(exists('.cr_hash'))get('.cr_hash')else getFromNamespace('.cr_hash','creditratingsystem')
dv_D<-'2023-01-01';dv_E<-'2024-01-02'
dv_target<-function()list(event='default',horizon=365,time_unit='days',probability_measure='PHYSICAL',conditioning='initially_performing')
dv_policy<-function(cutoff=.05)compile_credit_decision_policy(list(schema_version='1.0',policy_id=paste0('p',cutoff),version='1',approval_reference='bank-reference',known_at=dv_D,effective_from=dv_D,effective_until='2024-01-01',default_action='DECLINE',missing_action='BLOCKED',target=dv_target(),fields=list('risk.pd'=list(type='number')),rules=list(list(rule_id='approve',priority=1L,action='APPROVE',reason_code='PD_CUTOFF',when=list(list(field='risk.pd',op='le',value=cutoff))))))$value
dv_sources<-function(pd){timing<-list(as_of=dv_D,known_at=dv_D);list(risk=c(timing,list(pd=pd,target=dv_target(),freshness='CURRENT')),affordability=c(timing,list(status='AFFORDABLE')),eligibility=c(timing,list(status='ELIGIBLE')),operations=c(timing,list(status='CLEAR')))}
dv_offer<-function(id,profit=10)list(offer_id=id,version='1',known_at=dv_D,currency='EUR',target=dv_target(),risk_conditioning='CONDITIONAL_ON_THIS_ACCEPTED_OFFER',assumption_reference='scenario',support_status='SUPPORTED',takeup_probability=.5,conditional_booked_expected_loss=2,conditional_booked_npv=profit,ead=100,offer_cost=1)
dv_fixture<-function(){
 policies<-list(list(candidate_id='a',policy=dv_policy(.05),offer_rule_reference='rule-a'),list(candidate_id='b',policy=dv_policy(.2),offer_rule_reference='rule-b'));cases<-lapply(c('one','two'),function(id)list(case_id=id,decision_date=dv_D,weight=1,split_id='validation',prediction_reference='held-out',excluded_from_model_training=TRUE,excluded_from_calibration=TRUE));inputs<-list();for(p in policies)for(i in 1:2)inputs[[length(inputs)+1L]]<-c(list(candidate_id=p$candidate_id,case_id=cases[[i]]$case_id),dv_sources(c(.01,.1)[i]),list(offer=dv_offer(cases[[i]]$case_id),nonapproval_costs=list(REFER=2,DECLINE=0,BLOCKED=0)))
 outcomes<-list(list(case_id='one',funded=TRUE,complete=TRUE,booked_offer_hash=dv_hash(dv_offer('one')),funded_at=dv_D,funding_known_at=dv_D,outcome_end='2024-01-01',known_at=dv_E,defaulted=TRUE,economic_loss=50,net_profit=-40),list(case_id='two',funded=FALSE,complete=FALSE,booked_offer_hash=NULL,funded_at=NULL,funding_known_at=NULL,outcome_end=NULL,known_at=NULL,defaulted=NULL,economic_loss=NULL,net_profit=NULL))
 profile<-list(profile_id='selection',version='1',known_at=dv_D,currency='EUR',registered_at=dv_D,outcome_access_date=dv_E,evaluation_role='VALIDATION',prediction_design='HELD_OUT',split_id='validation',data_fingerprint='bank-declared-data',target=dv_target(),candidate_hashes=setNames(lapply(policies,dv_hash),c('a','b')),objective='expected_npv_per_application',constraints=list(list(constraint_id='loss',metric='expected_loss_per_application',operator='le',threshold=.75)),tie_break='candidate_id',tolerance=1e-12,loss_bounds=list(0,100),profit_bounds=list(-100,100))
 list(policy_candidates=policies,cases=cases,candidate_inputs=inputs,observed_outcomes=outcomes,evaluation_profile=profile,evaluation_cutoff=dv_E)
}
dv_error<-function(code,expr){e<-tryCatch(force(expr),error=identity);stopifnot(inherits(e,'creditratingsystem_error'),e$code==code)}
r<-do.call(evaluate_decision_grid,dv_fixture())$value;a<-r$candidates[[1]];b<-r$candidates[[2]]
stopifnot(a$metrics$approval_rate==.5,b$metrics$approval_rate==1,a$metrics$expected_loss_per_application==.5,b$metrics$expected_loss_per_application==1,a$metrics$expected_npv_per_application==2,b$metrics$expected_npv_per_application==4,a$status=='FEASIBLE',b$status=='INFEASIBLE',b$observed_outcomes$observed_pd==1,b$observed_outcomes$mature_matched_weight==1,b$observed_outcomes$case_status[[2]]$status=='NOT_FUNDED',is.null(b$observed_outcomes$full_candidate_causal_value));selected<-select_constrained_policy(r)$value;stopifnot(selected$selected_candidate_id=='a',selected$objective_value==2)
f<-dv_fixture();f$observed_outcomes[[1]]$complete<-FALSE;for(k in c('known_at','defaulted','economic_loss','net_profit'))f$observed_outcomes[[1]][k]<-list(NULL);r<-do.call(evaluate_decision_grid,f)$value$candidates[[1]]$observed_outcomes;stopifnot(is.null(r$observed_pd),identical(r$matched_funded_mean_loss_bounds,list(0,100)),identical(r$matched_funded_mean_profit_bounds,list(-100,100)),r$missing_outcome_weight==1);f$observed_outcomes[[2]]$defaulted<-FALSE;dv_error('DECISION_OUTCOME',do.call(evaluate_decision_grid,f))
f<-dv_fixture();for(i in seq_along(f$candidate_inputs))f$candidate_inputs[[i]]$offer$support_status<-'UNSUPPORTED';r<-do.call(evaluate_decision_grid,f)$value;stopifnot(all(vapply(r$candidates,function(x)x$status=='UNIDENTIFIED',TRUE)),all(vapply(r$candidates,function(x)is.null(x$metrics$expected_npv_per_application),TRUE)),select_constrained_policy(r)$value$status=='INFEASIBLE')
f<-dv_fixture();f$evaluation_profile$evaluation_role<-'TEST';r<-do.call(evaluate_decision_grid,f)$value;dv_error('DECISION_SPLIT',select_constrained_policy(r));f<-dv_fixture();f$cases[[1]]$excluded_from_model_training<-FALSE;dv_error('DECISION_SPLIT',do.call(evaluate_decision_grid,f));f<-dv_fixture();f$policy_candidates[[1]]$offer_rule_reference<-'changed';dv_error('DECISION_SELECTION_CONTRACT',do.call(evaluate_decision_grid,f));f<-dv_fixture();f$evaluation_profile$registered_at<-'2024-01-03';dv_error('DECISION_SELECTION_CONTRACT',do.call(evaluate_decision_grid,f))
f<-dv_fixture();f$evaluation_profile$constraints[[1]]$threshold<-2;r<-do.call(evaluate_decision_grid,f)$value;stopifnot(select_constrained_policy(r)$value$selected_candidate_id=='b');f$policy_candidates[[1]]$policy<-f$policy_candidates[[2]]$policy;f$evaluation_profile$candidate_hashes<-setNames(lapply(f$policy_candidates,dv_hash),c('a','b'));for(i in seq_along(f$candidate_inputs))if(f$candidate_inputs[[i]]$candidate_id=='b')f$candidate_inputs[[i]]$offer$conditional_booked_expected_loss<-1;r<-select_constrained_policy(do.call(evaluate_decision_grid,f))$value;stopifnot(r$selected_candidate_id=='b',identical(r$dominance,list(list(candidate_id='a',dominated_by='b'))))
dv_robust_fixture<-function(){
 rows<-lapply(1:2,function(i)c(list(case_id=c('near','far')[i],decision_date=dv_D,weight=1),dv_sources(c(.049,.01)[i]),list(offer_terms=list(offer_id=c('near','far')[i],version='1',amount=100,annual_rate=.1),utility_reference='scenario-values',utility_by_action=list(APPROVE=10,REFER=-1,DECLINE=0,BLOCKED=-2),feasible_by_action=list(APPROVE=TRUE,REFER=TRUE,DECLINE=TRUE,BLOCKED=TRUE))));low<-rows;high<-rows;high[[1]]$risk$pd<-.051;profile<-list(profile_id='robust',version='1',known_at=dv_D,currency='EUR',target=dv_target(),scenario_design='BOUNDED_GRID',generation_reference='two-shared-shocks',interpretation='PERTURBATION_NOT_CAUSAL',tolerance=1e-12)
 list(policy=dv_policy(),baseline_cases=rows,perturbation_scenarios=list(list(scenario_id='low',weight=.5,perturbation_reference='low',cases=low),list(scenario_id='high',weight=.5,perturbation_reference='high',cases=high)),robustness_profile=profile,as_of=dv_D)
}
f<-dv_robust_fixture();r<-do.call(assess_policy_robustness,f)$value;high<-r$scenarios[[1]];stopifnot(r$weighted_action_flip_rate==.25,r$worst_case_mean_regret==5,high$cases[[2]]$action_flipped,identical(high$cases[[2]]$changed_input_sources,list('risk')),!high$cases[[1]]$action_flipped,r$weighted_known_infeasible_action_rate==0)
f<-dv_robust_fixture();f$perturbation_scenarios[[1]]$cases[[1]]$utility_by_action['APPROVE']<-list(NULL);f$perturbation_scenarios[[2]]$cases[[2]]$feasible_by_action$APPROVE<-FALSE;r<-do.call(assess_policy_robustness,f)$value;stopifnot(is.null(r$worst_case_mean_regret),'utility_regret'%in%unlist(r$unidentified_dimensions),r$weighted_known_infeasible_action_rate==.25);f<-dv_robust_fixture();f$perturbation_scenarios[[1]]$weight<-1;dv_error('DECISION_ROBUSTNESS_CONTRACT',do.call(assess_policy_robustness,f))
cat('Native policy grid/selection/shared perturbation oracles PASS\n')
f<-dv_fixture();f$observed_outcomes[[1]]$funding_known_at<-'2024-01-03';r<-do.call(evaluate_decision_grid,f)$value;stopifnot(r$candidates[[1]]$observed_outcomes$matched_funded_weight==0,r$candidates[[1]]$observed_outcomes$case_status[[1]]$status=='FUTURE_FUNDING_EVIDENCE');r<-do.call(evaluate_decision_grid,dv_fixture())$value;r$candidates[[1]]$policy<-dv_policy(.3);r$sha256<-NULL;r$sha256<-dv_hash(r);dv_error('DECISION_SELECTION_CONTRACT',select_constrained_policy(r))
